<?php
 namespace App\Mail\Transport; use Illuminate\Support\Facades\Http; use Symfony\Component\Mailer\Exception\TransportException; use Symfony\Component\Mailer\SentMessage; use Symfony\Component\Mailer\Transport\AbstractTransport; use Symfony\Component\Mime\Address; use Symfony\Component\Mime\Email; class SendCloudTransport extends AbstractTransport { public function __construct(private string $apiUser, private string $apiKey) { parent::__construct(); } public function __toString(): string { return 'sendcloud'; } protected function doSend(SentMessage $message): void { $email = $message->getOriginalMessage(); if (!$email instanceof Email) { throw new TransportException('SendCloud requires an email message.'); } $addresses = static fn (array $items) => implode(';', array_map( static fn (Address $item) => $item->getAddress(), $items)); $data = [ 'apiUser' => $this->apiUser, 'apiKey' => $this->apiKey, 'from' => $email->getFrom()[0]->getAddress(), 'fromName' => $email->getFrom()[0]->getName(), 'to' => $addresses($email->getTo()), 'cc' => $addresses($email->getCc()), 'bcc' => $addresses($email->getBcc()), 'replyTo' => $addresses($email->getReplyTo()), 'subject' => $email->getSubject(), 'html' => $email->getHtmlBody(), 'plain' => $email->getTextBody(), ]; $request = Http::asForm()->timeout(30); foreach ($email->getAttachments() as $attachment) { $request->attach('attachments', $attachment->getBody(), $attachment->getFilename()); } $response = $request->post('https://api.sendcloud.net/apiv2/mail/send', array_filter($data, static fn ($value) => $value !== null && $value !== '')); if (!$response->successful() || $response->json('result') !== true) { throw new TransportException('SendCloud delivery failed (HTTP ' . $response->status() . ', code ' . ($response->json('statusCode') ?? 'unknown') . ').'); } } } 